@using sv_4894735467a64b5b9e51e64ffbedcea3.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize how the app looks and feels.</p>
    <hr />

    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-6">
                @* Theme *@
                <div class="mb-4">
                    <h5>Theme</h5>
                    @foreach (var theme in new[] { ("light", "Light ☀️"), ("dark", "Dark 🌙"), ("system", "System 💻") })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="theme-@theme.Item1"
                                   value="@theme.Item1"
                                   checked="@(_theme == theme.Item1)"
                                   @onchange="() => _theme = theme.Item1" />
                            <label class="form-check-label" for="theme-@theme.Item1">@theme.Item2</label>
                        </div>
                    }
                </div>

                @* Font Size *@
                <div class="mb-4">
                    <h5>Font Size</h5>
                    @foreach (var size in new[] { ("small", "Small"), ("medium", "Medium"), ("large", "Large") })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="font-@size.Item1"
                                   value="@size.Item1"
                                   checked="@(_fontSize == size.Item1)"
                                   @onchange="() => _fontSize = size.Item1" />
                            <label class="form-check-label" for="font-@size.Item1">@size.Item2</label>
                        </div>
                    }
                </div>

                @* Language *@
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                @* Compact Mode *@
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <br /><small class="text-muted">Reduce spacing and padding throughout the app</small>
                        </label>
                    </div>
                </div>
            </div>

            @* Live Preview *@
            <div class="col-md-6">
                <h5>Preview</h5>
                <div class="appearance-preview @PreviewThemeClass" style="font-size: @PreviewFontSize;">
                    <div class="preview-header">
                        <strong>Settings Dashboard</strong>
                    </div>
                    <div class="preview-body" style="padding: @(_compactMode ? "0.5rem" : "1rem");">
                        <p class="mb-2">This is a preview of your selected appearance settings.</p>
                        <div class="d-flex gap-2 mb-2">
                            <span class="badge bg-primary">Badge</span>
                            <span class="badge bg-secondary">Label</span>
                        </div>
                        <button class="btn btn-sm btn-primary me-1">Primary</button>
                        <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        <hr style="margin: @(_compactMode ? "0.5rem 0" : "1rem 0");" />
                        <small class="preview-meta">
                            Theme: @_theme · Size: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "on" : "off")
                        </small>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private string _theme = "system";
    private string _fontSize = "medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    private string PreviewThemeClass => _theme switch
    {
        "dark" => "preview-dark",
        "light" => "preview-light",
        _ => "preview-system"
    };

    private string PreviewFontSize => _fontSize switch
    {
        "small" => "0.85rem",
        "large" => "1.15rem",
        _ => "1rem"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-meta {
    opacity: 0.7;
}

/* Light theme preview */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
    border-color: #dee2e6;
}

/* Dark theme preview */
.preview-dark {
    background: #212529;
    color: #f8f9fa;
}

.preview-dark .preview-header {
    background: #2c3034;
    border-color: #495057;
}

.preview-dark hr {
    border-color: #495057;
}

/* System theme preview */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #212529 50%);
    color: #212529;
    position: relative;
}

.preview-system .preview-header {
    background: #e9ecef;
}

